// CLS-4: the opening book, generated by scripts/build-book.ts from lichess-org/chess-openings (CC0).
import { epd } from '../game/replay.ts';
import book from './book.json' with { type: 'json' };

const names: Record<string, string> = book;

export function inBook(fen: string): boolean {
  return epd(fen) in names;
}

/** The opening's name when a named line ends at this position. */
export function openingName(fen: string): string | null {
  return names[epd(fen)] || null;
}
